const sinAcentos = s => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '');

const clave = s => sinAcentos(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// Busca un campo del formulario por su nombre interno o por su etiqueta, sin depender de acentos ni mayúsculas.
function campo(datos, ...nombres) {
  const k = Object.keys(datos).find(c => nombres.includes(clave(c)));
  return k === undefined ? '' : String(datos[k] ?? '').trim();
}

// carmen ruiz → Carmen Ruiz
function nombre(s) {
  return String(s ?? '').trim().replace(/\s+/g, ' ').toLowerCase().split(' ')
    .map((p, i) => i > 0 && ['de', 'del', 'la', 'y'].includes(p) ? p : p.charAt(0).toUpperCase() + p.slice(1))
    .join(' ');
}

function prepararSolicitud(datos, hoy) {
  const s = {
    cliente: nombre(campo(datos, 'cliente', 'nombre y apellidos', 'nombre')),
    telefono: campo(datos, 'telefono').replace(/[^\d+]/g, ''),
    email: campo(datos, 'email', 'correo electronico', 'correo').toLowerCase(),
    producto: campo(datos, 'producto', 'modelo'),
    talla: campo(datos, 'talla'),
    comentario: campo(datos, 'comentario'),
    fecha: hoy,
  };
  const faltan = [];
  if (!s.cliente) faltan.push('nombre');
  if (!/^\+?\d{9,15}$/.test(s.telefono)) faltan.push('teléfono válido');
  if (!s.producto) faltan.push('modelo');
  if (!s.talla) faltan.push('talla');
  if (s.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s.email)) faltan.push('correo válido');
  s.clave = [clave(s.cliente), s.telefono, clave(s.producto), clave(s.talla), s.fecha].join('|');
  return { ...s, faltan };
}

const hoy = $now.setZone('Europe/Madrid').toISODate();
return $input.all().map(i => ({ json: prepararSolicitud(i.json, hoy) }));

function decidirSolicitudes(solicitudes, guardadas) {
  const vistas = new Set(guardadas.map(g => g.clave));
  return solicitudes.map(s => {
    if (s.faltan.length) return { ...s, accion: 'incompleta', motivo: `Falta: ${s.faltan.join(', ')}` };
    if (vistas.has(s.clave)) return { ...s, accion: 'repetida', motivo: 'Ya hay una solicitud de esta persona para este modelo y talla hoy' };
    vistas.add(s.clave);
    return { ...s, accion: 'nueva', motivo: '' };
  });
}

// Se ven todas las solicitudes del lote a la vez para no guardar dos veces la misma.
const solicitudes = $('Preparar solicitud').all().map(i => i.json);
const guardadas = $('Solicitudes guardadas').all().map(i => i.json).filter(g => g.id !== undefined);
return decidirSolicitudes(solicitudes, guardadas).map(json => ({ json }));

function avisosSolicitud(s, urlConfirmar) {
  const datos = [`- Cliente: ${s.cliente || '(sin nombre)'}`, `- Teléfono: ${s.telefono || '(sin teléfono)'}`,
    `- Correo: ${s.email || '(no lo ha dejado)'}`, `- Modelo y talla: ${s.producto || '?'} · ${s.talla || '?'}`,
    ...(s.comentario ? [`- Comentario: ${s.comentario}`] : [])];
  if (s.accion !== 'nueva') {
    return [{ destinatario: 'tienda', email: '', contexto: 'Solicitud de apartado',
      asunto: `Solicitud de apartado NO guardada: ${s.cliente || 'sin nombre'}`,
      mensaje: ['Hola, Marisa:', '', `Ha llegado una solicitud de apartado que no se ha guardado. Motivo: ${s.motivo}.`, '',
        ...datos, '', 'Si hace falta, llama a la clienta.', '', 'Este aviso lo envía el flujo "Solicitudes de apartado".'].join('\n') }];
  }
  const avisos = [{ destinatario: 'tienda', email: '', contexto: `Solicitud ${s.id}`,
    asunto: `Nueva solicitud de apartado nº ${s.id}: ${s.cliente}, ${s.producto} T${s.talla}`,
    mensaje: ['Hola, Marisa:', '', `Hay una solicitud de apartado nueva (nº ${s.id}). Todavía no hay apartado en la app: se crea cuando la clienta pague el abono inicial.`, '',
      ...datos, '', `Cuando pague, confírmala aquí con el nº ${s.id}, el precio, el abono y la forma de pago:`, urlConfirmar, '',
      'Este aviso lo envía el flujo "Solicitudes de apartado".'].join('\n') }];
  if (s.email) {
    avisos.push({ destinatario: 'cliente', email: s.email, contexto: `Solicitud ${s.id}`,
      asunto: 'Hemos recibido tu solicitud de apartado en Paso Firme',
      mensaje: [`Hola, ${s.cliente.split(' ')[0]}:`, '', `Hemos recibido tu solicitud para apartar ${s.producto} (talla ${s.talla}).`,
        'El apartado queda confirmado cuando pagues el abono inicial, de 5 € como mínimo, en la tienda o por Bizum. Te lo confirmaremos por correo.', '',
        `Número de solicitud: ${s.id}`, '', 'Zapatería Paso Firme'].join('\n') });
  }
  return avisos;
}

// Las nuevas llegan ya guardadas (con su número); las incompletas y repetidas, tal cual.
const base = $env.N8N_EDITOR_BASE_URL || 'http://localhost:5678';
const url = base.replace(/\/$/, '') + '/form/confirmar-solicitud';
return $input.all().flatMap(i => {
  const s = i.json.accion ? i.json : { ...i.json, accion: 'nueva' };
  return avisosSolicitud(s, url).map(json => ({ json }));
});
